import { test } from '@playwright/test';
import { AutomationEngine } from './engine';
import { StateManager } from './state-manager';
import * as path from 'path';
import * as fs from 'fs';

const engine = new AutomationEngine(path.join(process.cwd(), 'core/mappings.json'));
const stateManager = new StateManager(path.join(process.cwd(), 'core/state.json'));

// 2. Load Blueprint (generated by scenario_parser.js via the Studio UI)
const blueprintPath = path.join(process.cwd(), 'core/blueprint.json');
if (!fs.existsSync(blueprintPath)) {
    throw new Error('❌ blueprint.json not found! Upload your Excel in the Studio UI first.');
}
const scenarios: any[] = JSON.parse(fs.readFileSync(blueprintPath, 'utf8'));

// 3. Data-Driven Test Suite — one test per scenario row in the Excel
test.describe('Automated UAT Suite', () => {

    test.beforeAll(async ({ request }) => {
        const response = await request.get('http://localhost:3000').catch(() => null);
        if (!response || !response.ok()) {
            throw new Error('❌ Studio Server is not responding at http://localhost:3000. Start it with "npm run studio" first.');
        }
    });

    test.afterAll(async () => {
        await stateManager.persistState();
        console.log('✅ State persisted to core/state.json');
    });

    for (const scenario of scenarios) {
        test(`Scenario ${scenario.Scenario_ID}: ${scenario.Role}`, async ({ page }) => {
            // Create an isolated results directory per scenario
            const safeName = scenario.Scenario_ID.replace(/[^a-z0-9]/gi, '_');
            const resultsDir = path.join(process.cwd(), 'results', safeName);
            if (fs.existsSync(resultsDir)) fs.rmSync(resultsDir, { recursive: true, force: true });
            fs.mkdirSync(resultsDir, { recursive: true });

            console.log(`\n▶️  Starting: ${scenario.Scenario_ID} — ${scenario.Role}`);

            try {
                for (let i = 0; i < scenario.Flow.length; i++) {
                    const step = scenario.Flow[i];
                    // test.step makes each mapping key visible in the Playwright UI / Trace Viewer
                    await test.step(step.Mapping_Key, async () => {
                        await engine.runStep(page, step.Mapping_Key, step.Data, resultsDir, i);
                    });
                }
                console.log(`✅ PASSED: ${scenario.Scenario_ID}`);
            } catch (error: any) {
                console.error(`❌ FAILED: ${scenario.Scenario_ID} —`, error.message);
                await page.screenshot({ path: path.join(resultsDir, 'CRITICAL_ERROR.png'), fullPage: true });
                throw error;
            } finally {
                await page.screenshot({ path: path.join(resultsDir, 'FINAL_STATE.png'), fullPage: true });
            }
        });
    }
});
